// Clinical Nursing Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: prioritization, assessment findings and safe interventions.
import {q, mix} from './q.js';
const PP='Perry & Potter, Clinical Nursing Skills and Techniques', ROS='Rosdahl & Kowalski, Textbook of Basic Nursing';
const BASIC='Basic Care', LIFE='Clinical Care Through the Life Span', SYS='Clinical Care for Systems Diseases and Disorders';

export default {
 id:'clinical-nursing-1',
 event:'Clinical Nursing',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Perry & Potter’s Clinical Nursing Skills and Techniques and Rosdahl & Kowalski’s Textbook of Basic Nursing',
 plan:[{area:BASIC,weight:20},{area:LIFE,weight:20},{area:SYS,weight:60}],
 questions:mix([
  q(BASIC,'What is the correct order of the nursing process?','Assessment, diagnosis, planning, implementation, evaluation',['Diagnosis, assessment, implementation, planning, evaluation','Planning, assessment, diagnosis, evaluation, implementation','Assessment, planning, diagnosis, evaluation, implementation'],'B','The nursing process (ADPIE) begins with gathering data and ends with evaluating whether goals were met, which may restart the cycle.',ROS),
  q(BASIC,'Which patient should the nurse see first?','A patient with noisy, gurgling respirations',['A patient requesting pain medication','A patient who needs help to the bathroom','A patient asking about discharge'],'D','Airway problems come first in prioritization (ABCs and Maslow’s physiological needs). Gurgling suggests secretions blocking the airway.',ROS),
  q(BASIC,'What does SBAR stand for in nurse-to-provider communication?','Situation, Background, Assessment, Recommendation',['Symptoms, Blood pressure, Allergies, Results','Safety, Behavior, Action, Response','Summary, Baseline, Analysis, Report'],'A','SBAR organizes urgent information clearly and concisely, reducing communication errors.',PP),
  q(BASIC,'An apical pulse is 92 and the radial pulse taken at the same time is 78. What is the pulse deficit?','14 beats per minute',['78 beats per minute','92 beats per minute','170 beats per minute'],'C','Pulse deficit = apical − radial = 92 − 78 = 14. A deficit means some heartbeats are not reaching the periphery, as in atrial fibrillation.',PP),
  q(BASIC,'Which task can a nurse NOT delegate to unlicensed assistive personnel?','Assessing a newly admitted patient',['Taking routine vital signs','Bathing a stable, alert patient','Measuring intake and output'],'B','Assessment, teaching, evaluation and care of unstable patients require nursing judgment and cannot be delegated.',ROS),
  q(BASIC,'The nurse forgot to chart an assessment done earlier. What is correct?','Add a late entry labeled with the current date and time',['Write it as if it happened at the original time','Leave it out of the record','Ask another nurse to chart it'],'D','Late entries are clearly labeled. Backdating or omitting care is falsification, and care that is not documented is considered not done.',ROS),
  q(BASIC,'Which procedure requires surgical aseptic (sterile) technique?','Inserting a urinary catheter',['Giving oral medications','Taking a temperature','Applying an ice pack to a sprain'],'A','Entering a sterile body cavity, such as the bladder, requires sterile technique to prevent infection.',PP),
  q(BASIC,'A patient scores high risk on the Morse Fall Scale. Which intervention is most appropriate?','Low bed and call light in reach',['Keep all four side rails up','Restrain the patient at night','Encourage walking alone at night'],'C','Low bed, call light in reach, nonskid footwear and scheduled toileting reduce falls. Four raised rails may be a restraint and increase injury.',PP),
  q(BASIC,'How often should a bedbound patient at risk for pressure injuries be repositioned?','At least every 2 hours',['Every 8 hours','Once a shift','Only when the patient asks'],'B','Regular repositioning relieves pressure over bony prominences. Support surfaces and good nutrition also help prevent injury.',PP),
  q(BASIC,'Before giving any medication, which action best prevents errors?','Checking two patient identifiers',['Asking the patient’s room number','Relying on memory of the order','Checking the drug only once at the cart'],'D','Two identifiers and multiple checks of the rights of medication administration help prevent wrong-patient and wrong-drug errors.',PP),
  q(LIFE,'On the first day after delivery, a mother’s uterine fundus is soft and boggy above the umbilicus. What should the nurse do first?','Massage the fundus until it is firm',['Help the mother take a warm bath','Encourage her to rest flat','Document the finding and wait'],'A','A boggy uterus can lead to postpartum hemorrhage. Fundal massage helps it contract; a full bladder can also displace the uterus.',ROS),
  q(LIFE,'Which two medications are routinely given to newborns soon after birth?','Vitamin K and erythromycin ointment',['Insulin and iron drops','Antibiotics and acetaminophen','Hepatitis C vaccine and aspirin'],'C','Vitamin K prevents bleeding because newborns lack gut bacteria to make it. Erythromycin eye ointment prevents neonatal eye infection.',ROS),
  q(LIFE,'A newborn develops jaundice on day 3. Which statement about physiologic jaundice is true?','It usually appears after the first 24 hours',['It always appears in the first 24 hours','It means the baby has liver failure','It requires immediate surgery'],'B','Physiologic jaundice from immature liver function appears after 24 hours. Jaundice in the first 24 hours is pathologic and needs evaluation.',ROS),
  q(LIFE,'Which finding suggests dehydration in an infant?','A sunken anterior fontanel',['A bulging, tense fontanel','Frequent wet diapers','Moist mucous membranes'],'D','Signs include a sunken fontanel, dry mouth, fewer wet diapers, no tears and lethargy. A bulging fontanel suggests increased intracranial pressure.',ROS),
  q(LIFE,'How can a nurse reduce a 4-year-old’s fear before a procedure?','Use simple words and play with a doll',['Give a detailed medical explanation first','Surprise the child without warning','Separate the child from the parents'],'A','Preschoolers fear body harm. Simple explanations, play and having a parent present help them cope.',ROS),
  q(LIFE,'Which finding suggests delirium rather than dementia in an older adult?','Sudden, fluctuating confusion',['Gradual memory loss over years','Stable, unchanging confusion','Normal attention with poor memory'],'C','Delirium is acute, fluctuating and often reversible, caused by infection, drugs or dehydration. Dementia develops slowly over years.',ROS),
  q(LIFE,'How might a heart attack present in an older adult?','With fatigue or confusion, not chest pain',['Always with crushing, severe chest pain','Only with arm pain','With a high fever'],'B','Older adults, women and people with diabetes often have atypical symptoms, so a high index of suspicion is needed.',ROS),
  q(LIFE,'A depressed patient says, “I don’t see the point anymore.” What is the best response?','“Are you thinking about killing yourself?”',['“You have so much to live for.”','“Let’s talk about something happier.”','“Everyone feels down now and then.”'],'D','Asking directly about suicide does not increase risk and allows the nurse to assess safety and get help.',ROS),
  q(LIFE,'Which response is an example of therapeutic communication?','“Tell me more about what is worrying you.”',['“Why did you do that, exactly?”','“Don’t worry, it will be fine.”','“I would do it differently than you.”'],'A','Open-ended prompts encourage the patient to share. “Why” questions, false reassurance and giving opinions block communication.',ROS),
  q(LIFE,'A hospice patient is short of breath and anxious. Which medication is commonly used for comfort?','Low-dose morphine',['Large doses of IV fluid','A stimulant','An antibiotic'],'C','Morphine reduces the sensation of breathlessness and anxiety at the end of life. The goal of hospice care is comfort.',ROS),
  q(SYS,'Why is early ambulation encouraged after surgery?','It helps prevent clots and pneumonia',['It increases incision pain','It delays wound healing','It is only for patient comfort'],'B','Walking improves circulation, lung expansion and bowel function, reducing DVT, atelectasis, pneumonia and ileus.',PP),
  q(SYS,'In the post-anesthesia care unit, what is the nurse’s first priority?','Maintaining an open airway',['Checking the dressing','Giving pain medication','Updating the family members'],'D','Anesthesia depresses airway reflexes and breathing, so airway and breathing are assessed first.',PP),
  q(SYS,'Before giving digoxin, the nurse finds an apical pulse of 54. What should the nurse do?','Hold it and notify the provider',['Give the dose as ordered','Give half of the ordered dose','Give the full dose with food'],'A','Digoxin slows the heart. It is usually held if the adult apical pulse is below 60 and the provider is notified.',PP),
  q(SYS,'What INR range is usually therapeutic for a patient taking warfarin for atrial fibrillation?','2.0–3.0',['0.5–1.0','4.0–5.0','6.0–7.0'],'C','A normal INR is about 1.0. For most warfarin uses, the goal is 2.0–3.0; higher values increase bleeding risk.',PP),
  q(SYS,'A patient with chest pain is not relieved by rest or nitroglycerin. What should the nurse suspect?','Myocardial infarction',['Stable angina','Indigestion from a large meal','Anxiety attack'],'B','Stable angina is relieved by rest or nitroglycerin. Unrelieved pain suggests an MI and requires an ECG, cardiac markers and rapid intervention.',ROS),
  q(SYS,'A patient started on antihypertensive medication should be taught to:','Rise slowly from lying or sitting',['Stand up quickly to prevent dizziness','Stop the drug when blood pressure is normal','Double the dose if a dose is missed'],'D','Antihypertensives can cause orthostatic hypotension. Rising slowly prevents falls. Medication should not be stopped without the provider.',PP),
  q(SYS,'A patient with COPD who retains carbon dioxide is short of breath. What oxygen flow is usually ordered?','1–2 L/min by nasal cannula',['15 L/min by nonrebreather mask','No oxygen at all','10 L/min by simple mask'],'A','Controlled, low-flow oxygen targeting about 88–92% avoids worsening CO₂ retention while treating hypoxemia.',ROS),
  q(SYS,'For a patient with suspected pneumonia, when should the sputum culture be collected?','Before the first dose of antibiotics',['After three days of antibiotics','Only if antibiotics fail','At the time of discharge'],'C','Antibiotics can kill organisms in the sample, making the culture inaccurate. Cultures are obtained first, then treatment starts promptly.',PP),
  q(SYS,'The nurse notes continuous bubbling in the water-seal chamber of a chest tube system. What does this suggest?','An air leak in the system or the patient',['Normal chest tube function','The tube is clamped correctly now','The pneumothorax has fully resolved'],'B','Intermittent bubbling with breathing can be expected with a pneumothorax, but continuous bubbling suggests an air leak that should be located.',PP),
  q(SYS,'A patient with active tuberculosis is admitted. Which room is required?','A negative-pressure isolation room',['A semiprivate room with the door open','A room with positive pressure','Any room if the patient wears a gown'],'D','TB is airborne. Negative pressure keeps contaminated air from leaving the room, and staff wear N95 respirators.',PP),
  q(SYS,'Which type of insulin can be given intravenously?','Regular insulin',['Insulin glargine','NPH insulin','Insulin detemir'],'A','Regular insulin is the only insulin routinely given IV, as in DKA treatment. Intermediate and long-acting insulins are given subcutaneously.',PP),
  q(SYS,'A conscious patient’s blood glucose is 58 mg/dL. Using the “rule of 15,” what should the nurse do?','Give 15 g of fast carbs; recheck in 15 minutes',['Give 15 units of insulin','Wait 15 minutes and recheck without treatment','Give a large meal of protein'],'C','The rule of 15 treats mild hypoglycemia quickly and safely. Repeat if glucose stays low, then give a snack once it improves.',ROS),
  q(SYS,'What is an important sick-day rule for a patient with type 1 diabetes?','Keep taking insulin; test more often',['Stop all insulin while ill','Avoid all fluids until better','Check glucose only once a week'],'B','Illness raises blood glucose through stress hormones. Stopping insulin can lead to diabetic ketoacidosis.',ROS),
  q(SYS,'After a thyroidectomy, a patient reports tingling around the mouth and fingers. What complication should the nurse suspect?','Hypocalcemia',['Hyperkalemia','Hypoglycemia','Hypernatremia'],'D','The parathyroid glands can be injured or removed, causing hypocalcemia. Signs include tingling, muscle cramps and positive Chvostek and Trousseau signs.',ROS),
  q(SYS,'What is the most reliable way to confirm initial placement of a nasogastric tube?','An X-ray',['Listening for air over the stomach','Asking the patient to speak','Checking the color of drainage only'],'A','X-ray confirmation is the gold standard before the first use for feeding. Auscultation is not reliable.',PP),
  q(SYS,'How does a healthy new colostomy stoma look?','Pink to red and moist',['Pale and dry','Dark purple or black','Covered in white patches'],'C','A pink-red, moist stoma has good blood supply. A dusky or black stoma suggests poor circulation and must be reported.',PP),
  q(SYS,'Why is lactulose given to patients with cirrhosis and confusion?','It lowers blood ammonia levels',['It raises blood sugar levels','It stops bleeding varices','It increases appetite and weight'],'B','Lactulose draws ammonia into the colon to be excreted, treating hepatic encephalopathy.',ROS),
  q(SYS,'Which lab results support a diagnosis of acute pancreatitis?','Elevated serum amylase and lipase',['Low serum amylase and lipase','Elevated troponin levels','A low white blood cell count'],'D','Pancreatic enzymes leak into the blood when the pancreas is inflamed. Treatment includes NPO status, pain control and fluids.',ROS),
  q(SYS,'A patient with kidney failure has a potassium of 6.8 mEq/L. Which ECG change is associated with hyperkalemia?','Tall, peaked T waves',['Flat T waves with U waves','A very slow P wave','No change'],'A','Hyperkalemia causes peaked T waves and can progress to dangerous arrhythmias. Flat T waves and U waves suggest hypokalemia.',ROS),
  q(SYS,'A patient has an arteriovenous fistula in the left arm for dialysis. What should the nurse do?','No BPs or blood draws in that arm',['Take blood pressures only in that arm','Apply a tight bandage over the site','Check for a thrill only once a week'],'C','The fistula must be protected from compression and injury. The nurse feels for a thrill and listens for a bruit to confirm it is working.',ROS),
  q(SYS,'After a transurethral resection of the prostate (TURP), what is continuous bladder irrigation used for?','To prevent clots in the catheter',['To deliver liquid nutrition','To measure kidney function','To treat high blood pressure'],'B','Irrigation flushes blood and clots from the bladder. The nurse adjusts the rate to keep drainage light pink.',ROS),
  q(SYS,'For a patient with an ischemic stroke, within what time window is IV thrombolytic therapy usually given?','Within 3–4.5 hours',['Within 24 hours of onset','Within 7 days','At any time'],'D','Clot-dissolving drugs must be given early to save brain tissue. Bleeding must be ruled out with a CT scan first.',ROS),
  q(SYS,'How should the head of the bed be positioned for a patient with increased intracranial pressure?','Raised 30 degrees, head midline',['Flat with the head turned to the side','Trendelenburg with legs raised','Prone with the neck flexed'],'A','Elevation and a midline head position promote venous drainage from the brain, helping lower ICP.',PP),
  q(SYS,'In a neurological check, what does PERRLA describe?','Pupils equal, round, reactive to light and accommodation',['Pulse, electrolytes, respirations and lung assessment','Pain, edema, redness and loss of function','Posture, reflexes and range of motion'],'C','Changes in pupil size or reactivity can signal increasing intracranial pressure and must be reported immediately.',PP),
  q(SYS,'After a fall, an older adult’s leg is shortened and externally rotated. What should the nurse suspect?','Hip fracture',['Knee sprain','Ankle dislocation','Muscle cramp'],'B','A shortened, externally rotated leg with groin pain is a classic sign of a hip fracture.',ROS),
  q(SYS,'A patient in a new leg cast reports severe pain that is not relieved by medication and increases when the toes are stretched. What should the nurse suspect?','Compartment syndrome',['Normal healing pain','A loose cast','Muscle spasm only'],'D','Rising pressure inside a muscle compartment can cut off blood flow. It is an emergency that may require the cast to be split or surgery.',ROS),
  q(SYS,'An IV site is cool, pale and swollen, and the fluid is running slowly. What should the nurse do first?','Stop the infusion',['Increase the flow rate','Apply a tight dressing','Flush the IV forcefully'],'A','These are signs of infiltration. Stop the infusion, remove the catheter, elevate the arm and restart the IV at another site.',PP),
  q(SYS,'Which lab value is monitored closely in a patient receiving total parenteral nutrition (TPN)?','Blood glucose',['Hemoglobin A1c only','Urine color only','Bone density'],'C','TPN contains concentrated dextrose, which can cause hyperglycemia. Glucose is checked regularly, and TPN is not stopped abruptly.',PP),
  q(SYS,'Using the Parkland formula (4 mL × kg × %TBSA), how much fluid should a 70-kg adult with 30% burns receive in the first 8 hours?','4,200 mL',['2,100 mL','8,400 mL','12,600 mL'],'B','Total = 4 × 70 × 30 = 8,400 mL in 24 hours. Half is given in the first 8 hours from the time of injury: 4,200 mL.',ROS),
  q(SYS,'During a blood transfusion, the patient develops chills, fever and back pain. What should the nurse do first?','Stop the transfusion; keep the line open',['Slow the transfusion rate by half','Give the remaining blood quickly','Document it and continue the unit'],'D','These signs suggest a transfusion reaction. Stop the blood immediately, maintain IV access with saline, notify the provider and blood bank and monitor the patient.',PP)
 ],127)
};
